// Copies data/cards.json + data/scoring.json into js/data.js so the site
// works when index.html is opened straight from the folder (file://),
// where browsers block fetch() of local JSON.
// Run after editing either JSON file:  node tools/build-data.js
const fs = require("fs");
const path = require("path");
const root = path.join(__dirname, "..");
const cards = JSON.parse(fs.readFileSync(path.join(root, "data/cards.json"), "utf8"));
const scoring = JSON.parse(fs.readFileSync(path.join(root, "data/scoring.json"), "utf8"));
const out =
  "// GENERATED by tools/build-data.js from data/*.json. Edit the JSON, not this file.\n" +
  "window.CM_DATA = " + JSON.stringify({ cards, scoring }) + ";\n";
fs.writeFileSync(path.join(root, "js/data.js"), out);
console.log("js/data.js written (" + out.length + " bytes)");
